// Extract answer from LLM response
const response = $input.item.json;
let answer = 'Sorry, I could not generate a response.';
let sources = ['Knowledge Base: executive-summary.md', 'Knowledge Base: CLAUDE.md'];

try {
  if (response.choices && response.choices[0] && response.choices[0].message) {
    answer = response.choices[0].message.content;
  }
} catch (error) {
  answer = 'Error processing response: ' + error.message;
}

// Format final response
return {
  answer: answer,
  sources: sources,
  pipeline: 'chatbot-knowledge',
  sessionId: $('Parse Input').item.json.sessionId,
  timestamp: new Date().toISOString(),
  paragraphsUsed: $('Knowledge Search').item.json.paragraphsFound,
  model: 'meta-llama/llama-3.3-70b-instruct:free'
};

// Error handler
const error = $input.item.json.error || 'Unknown error';
const message = typeof error === 'string' ? error : error.message || 'An error occurred';

return {
  error: true,
  message: message,
  pipeline: 'chatbot-knowledge',
  timestamp: new Date().toISOString()
};
